create table public.rooms_v2 (id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties_v2(id) on delete restrict, label text not null, description text, status public.record_status not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz, unique(property_id,label)); alter table public.rooms_v2 enable row level security;
